def valid_utf8(data):
    i = 0
    n = len(data)
    while i < n:
        byte = data[i]
        if (byte & 0b10000000) == 0:
            num_bytes = 1                                          # explicit comparison against the 1 byte pattern
        elif (byte & 0b11100000) == 0b11000000:
            num_bytes = 2                                            # explicit comparison against the 2 byte pattern
        elif (byte & 0b11110000) == 0b11100000:
            num_bytes = 3                                             # explicit comparison against the 3 byte pattern
        elif (byte & 0b11111000) == 0b11110000:
            num_bytes = 4                                              # explicit comparison against the 4 byte pattern
        else:
            return False
        if i + num_bytes > n:
            return False
        for k in range(1, num_bytes):
            if (data[i + k] & 0b11000000) != 0b10000000:
                return False
        i += num_bytes
    return True


if __name__ == "__main__":
    print(valid_utf8([197, 130, 1]))

