import java.util.*;

public class Main {
    boolean validUtf8(int[] data) {
        int i = 0, n = data.length;
        while (i < n) {
            int b = data[i];
            int numBytes;
            if ((b & 0b10000000) == 0) {
                numBytes = 1;                                              // explicit comparison against the 1 byte pattern
            } else if ((b & 0b11100000) == 0b11000000) {
                numBytes = 2;                                                // explicit comparison against the 2 byte pattern
            } else if ((b & 0b11110000) == 0b11100000) {
                numBytes = 3;                                                 // explicit comparison against the 3 byte pattern
            } else if ((b & 0b11111000) == 0b11110000) {
                numBytes = 4;                                                  // explicit comparison against the 4 byte pattern
            } else {
                return false;
            }
            if (i + numBytes > n) return false;
            for (int k = 1; k < numBytes; k++) {
                if ((data[i + k] & 0b11000000) != 0b10000000) return false;
            }
            i += numBytes;
        }
        return true;
    }

    public static void main(String[] args) {
        Main solution = new Main();
        System.out.println(solution.validUtf8(new int[]{197, 130, 1}));
    }
}

